-- =============================================================================
-- Souk Atlas : schéma de la base (tables, contraintes, séquences, index)
-- Syntaxe compatible Oracle 19c / 21c (version utilisée en cours et aux examens).
--
-- Conventions :
--   * clé primaire "id" en GENERATED BY DEFAULT AS IDENTITY (Oracle 12c+) :
--     BY DEFAULT (et non ALWAYS) permet aux données de démo d'imposer des id ;
--   * clés étrangères nommées id_<table> ;
--   * contraintes nommées PK_, FK_, CK_, UQ_ pour des messages d'erreur lisibles ;
--   * prix en NUMBER(12,2), stockés HORS TAXE (la TVA est calculée) ;
--   * pas de type BOOLEAN en SQL avant 23ai : NUMBER(1) + CHECK (0, 1).
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Utilisateurs et sécurité
-- -----------------------------------------------------------------------------
CREATE TABLE utilisateur (
    id                      NUMBER GENERATED BY DEFAULT AS IDENTITY,
    email                   VARCHAR2(254)  NOT NULL,
    mot_de_passe_hash       VARCHAR2(255)  NOT NULL,
    nom                     VARCHAR2(100)  NOT NULL,
    telephone               VARCHAR2(20),
    ville                   VARCHAR2(60),
    role                    VARCHAR2(10)   DEFAULT 'CLIENT' NOT NULL,
    statut                  VARCHAR2(10)   DEFAULT 'ACTIF'  NOT NULL,
    date_creation           DATE           DEFAULT SYSDATE  NOT NULL,
    date_derniere_connexion DATE,
    CONSTRAINT pk_utilisateur PRIMARY KEY (id),
    CONSTRAINT uq_utilisateur_email UNIQUE (email),
    -- L'email est stocké en minuscules : l'unicité ne dépend pas de la casse
    CONSTRAINT ck_utilisateur_email CHECK (email = LOWER(email) AND email LIKE '%_@_%._%'),
    CONSTRAINT ck_utilisateur_role CHECK (role IN ('CLIENT', 'VENDEUR', 'ADMIN')),
    CONSTRAINT ck_utilisateur_statut CHECK (statut IN ('ACTIF', 'DESACTIVE'))
);

-- Sert à limiter les tentatives de connexion (étape 2)
CREATE TABLE tentative_connexion (
    id              NUMBER GENERATED BY DEFAULT AS IDENTITY,
    email           VARCHAR2(254) NOT NULL,
    adresse_ip      VARCHAR2(45),
    reussie         NUMBER(1)     NOT NULL,
    date_tentative  TIMESTAMP     DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_tentative_connexion PRIMARY KEY (id),
    CONSTRAINT ck_tentative_reussie CHECK (reussie IN (0, 1))
);
CREATE INDEX ix_tentative_email_date ON tentative_connexion (email, date_tentative);

-- -----------------------------------------------------------------------------
-- Marketplace : boutiques, catégories, produits
-- -----------------------------------------------------------------------------
CREATE TABLE boutique (
    id             NUMBER GENERATED BY DEFAULT AS IDENTITY,
    id_vendeur     NUMBER         NOT NULL,
    nom            VARCHAR2(100)  NOT NULL,
    description    VARCHAR2(2000),
    ville          VARCHAR2(60),
    statut         VARCHAR2(10)   DEFAULT 'EN_ATTENTE' NOT NULL,
    date_creation  DATE           DEFAULT SYSDATE NOT NULL,
    CONSTRAINT pk_boutique PRIMARY KEY (id),
    CONSTRAINT fk_boutique_vendeur FOREIGN KEY (id_vendeur) REFERENCES utilisateur (id),
    -- Une seule boutique par vendeur (et l'index unique sert aussi d'index de FK)
    CONSTRAINT uq_boutique_vendeur UNIQUE (id_vendeur),
    CONSTRAINT uq_boutique_nom UNIQUE (nom),
    CONSTRAINT ck_boutique_statut CHECK (statut IN ('EN_ATTENTE', 'VALIDEE', 'REFUSEE', 'SUSPENDUE'))
);

-- Arbre des catégories (parcouru avec CONNECT BY), partagé marketplace / annonces
CREATE TABLE categorie (
    id         NUMBER GENERATED BY DEFAULT AS IDENTITY,
    nom        VARCHAR2(80) NOT NULL,
    id_parent  NUMBER,
    CONSTRAINT pk_categorie PRIMARY KEY (id),
    CONSTRAINT fk_categorie_parent FOREIGN KEY (id_parent) REFERENCES categorie (id),
    CONSTRAINT uq_categorie_parent_nom UNIQUE (id_parent, nom)
);
CREATE INDEX ix_categorie_parent ON categorie (id_parent);

CREATE TABLE produit (
    id             NUMBER GENERATED BY DEFAULT AS IDENTITY,
    id_boutique    NUMBER         NOT NULL,
    id_categorie   NUMBER         NOT NULL,
    nom            VARCHAR2(200)  NOT NULL,
    description    VARCHAR2(4000),
    prix_ht        NUMBER(12, 2)  NOT NULL,
    stock          NUMBER(10)     DEFAULT 0 NOT NULL,
    statut         VARCHAR2(10)   DEFAULT 'ACTIF' NOT NULL,
    -- Maintenues par le trigger TRG_AVIS_NOTE_MOYENNE
    note_moyenne   NUMBER(3, 2),
    nb_avis        NUMBER(10)     DEFAULT 0 NOT NULL,
    date_creation  DATE           DEFAULT SYSDATE NOT NULL,
    CONSTRAINT pk_produit PRIMARY KEY (id),
    CONSTRAINT fk_produit_boutique FOREIGN KEY (id_boutique) REFERENCES boutique (id),
    CONSTRAINT fk_produit_categorie FOREIGN KEY (id_categorie) REFERENCES categorie (id),
    CONSTRAINT ck_produit_prix CHECK (prix_ht > 0),
    -- Dernier rempart contre un stock négatif (le package contrôle avant)
    CONSTRAINT ck_produit_stock CHECK (stock >= 0),
    CONSTRAINT ck_produit_statut CHECK (statut IN ('ACTIF', 'INACTIF')),
    CONSTRAINT ck_produit_note CHECK (note_moyenne BETWEEN 1 AND 5)
);
CREATE INDEX ix_produit_boutique ON produit (id_boutique);
CREATE INDEX ix_produit_categorie ON produit (id_categorie);
-- Index sur fonction : accélère l'autocomplétion "LOWER(nom) LIKE 'smart%'"
CREATE INDEX ix_produit_nom_lower ON produit (LOWER(nom));

CREATE TABLE produit_photo (
    id          NUMBER GENERATED BY DEFAULT AS IDENTITY,
    id_produit  NUMBER        NOT NULL,
    chemin      VARCHAR2(255) NOT NULL,
    ordre       NUMBER(2)     DEFAULT 1 NOT NULL,
    CONSTRAINT pk_produit_photo PRIMARY KEY (id),
    CONSTRAINT fk_produit_photo_produit FOREIGN KEY (id_produit)
        REFERENCES produit (id) ON DELETE CASCADE
);
CREATE INDEX ix_produit_photo_produit ON produit_photo (id_produit);

-- Rempli par le trigger TRG_PRODUIT_HISTORIQUE_PRIX
CREATE TABLE historique_prix (
    id               NUMBER GENERATED BY DEFAULT AS IDENTITY,
    id_produit       NUMBER        NOT NULL,
    ancien_prix_ht   NUMBER(12, 2) NOT NULL,
    nouveau_prix_ht  NUMBER(12, 2) NOT NULL,
    date_changement  DATE          DEFAULT SYSDATE NOT NULL,
    modifie_par      VARCHAR2(128),
    CONSTRAINT pk_historique_prix PRIMARY KEY (id),
    CONSTRAINT fk_historique_prix_produit FOREIGN KEY (id_produit)
        REFERENCES produit (id) ON DELETE CASCADE
);
CREATE INDEX ix_historique_prix_produit ON historique_prix (id_produit, date_changement);

-- Promotion sur UN produit OU sur UNE catégorie (et toutes ses sous-catégories)
CREATE TABLE promotion (
    id            NUMBER GENERATED BY DEFAULT AS IDENTITY,
    libelle       VARCHAR2(100) NOT NULL,
    pourcentage   NUMBER(5, 2)  NOT NULL,
    date_debut    DATE          NOT NULL,
    date_fin      DATE          NOT NULL,
    id_produit    NUMBER,
    id_categorie  NUMBER,
    actif         NUMBER(1)     DEFAULT 1 NOT NULL,
    CONSTRAINT pk_promotion PRIMARY KEY (id),
    CONSTRAINT fk_promotion_produit FOREIGN KEY (id_produit) REFERENCES produit (id),
    CONSTRAINT fk_promotion_categorie FOREIGN KEY (id_categorie) REFERENCES categorie (id),
    CONSTRAINT ck_promotion_pourcentage CHECK (pourcentage > 0 AND pourcentage <= 90),
    CONSTRAINT ck_promotion_dates CHECK (date_fin > date_debut),
    CONSTRAINT ck_promotion_actif CHECK (actif IN (0, 1)),
    -- Exactement une cible : le produit OU la catégorie
    CONSTRAINT ck_promotion_cible CHECK (
        (id_produit IS NOT NULL AND id_categorie IS NULL)
        OR (id_produit IS NULL AND id_categorie IS NOT NULL))
);
CREATE INDEX ix_promotion_produit ON promotion (id_produit);
CREATE INDEX ix_promotion_categorie ON promotion (id_categorie);

-- -----------------------------------------------------------------------------
-- Panier
-- -----------------------------------------------------------------------------
CREATE TABLE panier (
    id              NUMBER GENERATED BY DEFAULT AS IDENTITY,
    id_utilisateur  NUMBER NOT NULL,
    date_maj        DATE   DEFAULT SYSDATE NOT NULL,
    CONSTRAINT pk_panier PRIMARY KEY (id),
    CONSTRAINT fk_panier_utilisateur FOREIGN KEY (id_utilisateur) REFERENCES utilisateur (id),
    CONSTRAINT uq_panier_utilisateur UNIQUE (id_utilisateur)
);

CREATE TABLE panier_ligne (
    id          NUMBER GENERATED BY DEFAULT AS IDENTITY,
    id_panier   NUMBER     NOT NULL,
    id_produit  NUMBER     NOT NULL,
    quantite    NUMBER(5)  NOT NULL,
    date_ajout  DATE       DEFAULT SYSDATE NOT NULL,
    CONSTRAINT pk_panier_ligne PRIMARY KEY (id),
    CONSTRAINT fk_panier_ligne_panier FOREIGN KEY (id_panier) REFERENCES panier (id) ON DELETE CASCADE,
    CONSTRAINT fk_panier_ligne_produit FOREIGN KEY (id_produit) REFERENCES produit (id) ON DELETE CASCADE,
    -- Un produit n'apparaît qu'une fois par panier : on augmente la quantité
    CONSTRAINT uq_panier_ligne UNIQUE (id_panier, id_produit),
    CONSTRAINT ck_panier_ligne_quantite CHECK (quantite > 0)
);
CREATE INDEX ix_panier_ligne_produit ON panier_ligne (id_produit);

-- -----------------------------------------------------------------------------
-- Commandes et paiements
-- Un achat (même reference_achat) donne une commande PAR BOUTIQUE.
-- -----------------------------------------------------------------------------
CREATE SEQUENCE seq_numero_commande START WITH 1 NOCACHE;
CREATE SEQUENCE seq_reference_achat START WITH 1 NOCACHE;

CREATE TABLE commande (
    id                   NUMBER GENERATED BY DEFAULT AS IDENTITY,
    numero               VARCHAR2(20)  NOT NULL,
    reference_achat      VARCHAR2(20)  NOT NULL,
    id_client            NUMBER        NOT NULL,
    id_boutique          NUMBER        NOT NULL,
    statut               VARCHAR2(10)  DEFAULT 'EN_ATTENTE' NOT NULL,
    total_ht             NUMBER(12, 2) DEFAULT 0 NOT NULL,
    tva                  NUMBER(12, 2) DEFAULT 0 NOT NULL,
    total_ttc            NUMBER(12, 2) DEFAULT 0 NOT NULL,
    mode_paiement        VARCHAR2(10)  NOT NULL,
    adresse_livraison    VARCHAR2(400) NOT NULL,
    ville_livraison      VARCHAR2(60)  NOT NULL,
    telephone_livraison  VARCHAR2(20)  NOT NULL,
    score_risque         NUMBER(3),
    date_commande        DATE          DEFAULT SYSDATE NOT NULL,
    date_paiement        DATE,
    date_expedition      DATE,
    date_livraison       DATE,
    date_annulation      DATE,
    CONSTRAINT pk_commande PRIMARY KEY (id),
    CONSTRAINT uq_commande_numero UNIQUE (numero),
    CONSTRAINT fk_commande_client FOREIGN KEY (id_client) REFERENCES utilisateur (id),
    CONSTRAINT fk_commande_boutique FOREIGN KEY (id_boutique) REFERENCES boutique (id),
    CONSTRAINT ck_commande_statut CHECK (statut IN ('EN_ATTENTE', 'PAYEE', 'EXPEDIEE', 'LIVREE', 'ANNULEE')),
    CONSTRAINT ck_commande_mode CHECK (mode_paiement IN ('CARTE', 'LIVRAISON')),
    CONSTRAINT ck_commande_totaux CHECK (total_ttc = total_ht + tva AND total_ht >= 0),
    CONSTRAINT ck_commande_score CHECK (score_risque BETWEEN 0 AND 100)
);
CREATE INDEX ix_commande_client ON commande (id_client, date_commande);
CREATE INDEX ix_commande_boutique ON commande (id_boutique, date_commande);
CREATE INDEX ix_commande_reference ON commande (reference_achat);

CREATE TABLE commande_ligne (
    id                NUMBER GENERATED BY DEFAULT AS IDENTITY,
    id_commande       NUMBER        NOT NULL,
    id_produit        NUMBER        NOT NULL,
    -- Copiés au moment de la commande : une facture ne change jamais,
    -- même si le vendeur modifie ensuite le nom ou le prix du produit
    nom_produit       VARCHAR2(200) NOT NULL,
    prix_unitaire_ht  NUMBER(12, 2) NOT NULL,
    quantite          NUMBER(5)     NOT NULL,
    total_ligne_ht    NUMBER(12, 2) NOT NULL,
    CONSTRAINT pk_commande_ligne PRIMARY KEY (id),
    CONSTRAINT fk_commande_ligne_commande FOREIGN KEY (id_commande) REFERENCES commande (id),
    CONSTRAINT fk_commande_ligne_produit FOREIGN KEY (id_produit) REFERENCES produit (id),
    CONSTRAINT uq_commande_ligne UNIQUE (id_commande, id_produit),
    CONSTRAINT ck_commande_ligne_quantite CHECK (quantite > 0),
    CONSTRAINT ck_commande_ligne_total CHECK (total_ligne_ht = prix_unitaire_ht * quantite)
);
CREATE INDEX ix_commande_ligne_produit ON commande_ligne (id_produit);

-- Paiement SIMULÉ : jamais de numéro de carte complet, seulement les 4 derniers chiffres
CREATE TABLE paiement (
    id                NUMBER GENERATED BY DEFAULT AS IDENTITY,
    id_commande       NUMBER        NOT NULL,
    mode_paiement     VARCHAR2(10)  NOT NULL,
    montant           NUMBER(12, 2) NOT NULL,
    statut            VARCHAR2(10)  NOT NULL,
    carte_4_derniers  CHAR(4),
    date_paiement     DATE          DEFAULT SYSDATE NOT NULL,
    CONSTRAINT pk_paiement PRIMARY KEY (id),
    CONSTRAINT fk_paiement_commande FOREIGN KEY (id_commande) REFERENCES commande (id),
    CONSTRAINT uq_paiement_commande UNIQUE (id_commande),
    CONSTRAINT ck_paiement_mode CHECK (mode_paiement IN ('CARTE', 'LIVRAISON')),
    CONSTRAINT ck_paiement_statut CHECK (statut IN ('EN_ATTENTE', 'ACCEPTE', 'REMBOURSE')),
    CONSTRAINT ck_paiement_carte CHECK (
        (mode_paiement = 'CARTE' AND REGEXP_LIKE(carte_4_derniers, '^[0-9]{4}$'))
        OR (mode_paiement = 'LIVRAISON' AND carte_4_derniers IS NULL))
);

-- Un avis n'est possible qu'après une commande livrée (contrôlé par PKG_AVIS)
CREATE TABLE avis (
    id              NUMBER GENERATED BY DEFAULT AS IDENTITY,
    id_produit      NUMBER         NOT NULL,
    id_utilisateur  NUMBER         NOT NULL,
    note            NUMBER(1)      NOT NULL,
    commentaire     VARCHAR2(2000),
    statut          VARCHAR2(10)   DEFAULT 'PUBLIE' NOT NULL,
    date_avis       DATE           DEFAULT SYSDATE NOT NULL,
    CONSTRAINT pk_avis PRIMARY KEY (id),
    CONSTRAINT fk_avis_produit FOREIGN KEY (id_produit) REFERENCES produit (id),
    CONSTRAINT fk_avis_utilisateur FOREIGN KEY (id_utilisateur) REFERENCES utilisateur (id),
    CONSTRAINT uq_avis_produit_utilisateur UNIQUE (id_produit, id_utilisateur),
    CONSTRAINT ck_avis_note CHECK (note BETWEEN 1 AND 5),
    CONSTRAINT ck_avis_statut CHECK (statut IN ('PUBLIE', 'MASQUE'))
);
CREATE INDEX ix_avis_utilisateur ON avis (id_utilisateur);

-- -----------------------------------------------------------------------------
-- Petites annonces « Occasion »
-- -----------------------------------------------------------------------------
CREATE TABLE annonce (
    id                NUMBER GENERATED BY DEFAULT AS IDENTITY,
    id_utilisateur    NUMBER         NOT NULL,
    id_categorie      NUMBER         NOT NULL,
    titre             VARCHAR2(150)  NOT NULL,
    description       VARCHAR2(4000) NOT NULL,
    prix              NUMBER(12, 2)  NOT NULL,
    ville             VARCHAR2(60)   NOT NULL,
    statut            VARCHAR2(15)   DEFAULT 'EN_MODERATION' NOT NULL,
    -- Calculé par le moteur C++ (étape 8) ; NULL tant qu'il n'existe pas
    score_risque      NUMBER(3),
    motif_refus       VARCHAR2(500),
    date_publication  DATE           DEFAULT SYSDATE NOT NULL,
    date_expiration   DATE           NOT NULL,
    CONSTRAINT pk_annonce PRIMARY KEY (id),
    CONSTRAINT fk_annonce_utilisateur FOREIGN KEY (id_utilisateur) REFERENCES utilisateur (id),
    CONSTRAINT fk_annonce_categorie FOREIGN KEY (id_categorie) REFERENCES categorie (id),
    CONSTRAINT ck_annonce_prix CHECK (prix >= 0),
    CONSTRAINT ck_annonce_statut CHECK (statut IN ('EN_MODERATION', 'EN_LIGNE', 'REFUSEE', 'VENDUE', 'EXPIREE')),
    CONSTRAINT ck_annonce_score CHECK (score_risque BETWEEN 0 AND 100),
    CONSTRAINT ck_annonce_dates CHECK (date_expiration > date_publication)
);
CREATE INDEX ix_annonce_utilisateur ON annonce (id_utilisateur);
CREATE INDEX ix_annonce_categorie ON annonce (id_categorie);
-- Recherche typique : annonces en ligne d'une ville, les plus récentes d'abord
CREATE INDEX ix_annonce_statut_ville ON annonce (statut, ville, date_publication);

CREATE TABLE annonce_photo (
    id          NUMBER GENERATED BY DEFAULT AS IDENTITY,
    id_annonce  NUMBER        NOT NULL,
    chemin      VARCHAR2(255) NOT NULL,
    ordre       NUMBER(2)     DEFAULT 1 NOT NULL,
    CONSTRAINT pk_annonce_photo PRIMARY KEY (id),
    CONSTRAINT fk_annonce_photo_annonce FOREIGN KEY (id_annonce)
        REFERENCES annonce (id) ON DELETE CASCADE
);
CREATE INDEX ix_annonce_photo_annonce ON annonce_photo (id_annonce);

-- Clé primaire composée : un utilisateur ne met une annonce en favori qu'une fois
CREATE TABLE favori (
    id_utilisateur  NUMBER NOT NULL,
    id_annonce      NUMBER NOT NULL,
    date_ajout      DATE   DEFAULT SYSDATE NOT NULL,
    CONSTRAINT pk_favori PRIMARY KEY (id_utilisateur, id_annonce),
    CONSTRAINT fk_favori_utilisateur FOREIGN KEY (id_utilisateur) REFERENCES utilisateur (id),
    CONSTRAINT fk_favori_annonce FOREIGN KEY (id_annonce) REFERENCES annonce (id) ON DELETE CASCADE
);
-- La PK couvre id_utilisateur ; id_annonce a besoin de son propre index
CREATE INDEX ix_favori_annonce ON favori (id_annonce);

-- Un signalement vise UNE cible parmi annonce, avis ou produit.
-- Trois FK facultatives (plutôt qu'un "id_cible" générique) : Oracle garantit
-- ainsi que la cible existe vraiment.
CREATE TABLE signalement (
    id                NUMBER GENERATED BY DEFAULT AS IDENTITY,
    id_auteur         NUMBER         NOT NULL,
    id_annonce        NUMBER,
    id_avis           NUMBER,
    id_produit        NUMBER,
    motif             VARCHAR2(20)   NOT NULL,
    commentaire       VARCHAR2(1000),
    statut            VARCHAR2(10)   DEFAULT 'OUVERT' NOT NULL,
    id_moderateur     NUMBER,
    date_signalement  DATE           DEFAULT SYSDATE NOT NULL,
    date_traitement   DATE,
    CONSTRAINT pk_signalement PRIMARY KEY (id),
    CONSTRAINT fk_signalement_auteur FOREIGN KEY (id_auteur) REFERENCES utilisateur (id),
    CONSTRAINT fk_signalement_annonce FOREIGN KEY (id_annonce) REFERENCES annonce (id) ON DELETE CASCADE,
    CONSTRAINT fk_signalement_avis FOREIGN KEY (id_avis) REFERENCES avis (id) ON DELETE CASCADE,
    CONSTRAINT fk_signalement_produit FOREIGN KEY (id_produit) REFERENCES produit (id) ON DELETE CASCADE,
    CONSTRAINT fk_signalement_moderateur FOREIGN KEY (id_moderateur) REFERENCES utilisateur (id),
    CONSTRAINT ck_signalement_cible CHECK (
        NVL2(id_annonce, 1, 0) + NVL2(id_avis, 1, 0) + NVL2(id_produit, 1, 0) = 1),
    CONSTRAINT ck_signalement_motif CHECK (motif IN ('ARNAQUE', 'CONTREFACON', 'INAPPROPRIE', 'DOUBLON', 'AUTRE')),
    CONSTRAINT ck_signalement_statut CHECK (statut IN ('OUVERT', 'APPROUVE', 'REJETE'))
);
CREATE INDEX ix_signalement_auteur ON signalement (id_auteur);
CREATE INDEX ix_signalement_annonce ON signalement (id_annonce);
CREATE INDEX ix_signalement_avis ON signalement (id_avis);
CREATE INDEX ix_signalement_produit ON signalement (id_produit);
CREATE INDEX ix_signalement_moderateur ON signalement (id_moderateur);
CREATE INDEX ix_signalement_statut ON signalement (statut, date_signalement);

-- -----------------------------------------------------------------------------
-- Messagerie (autour d'une annonce)
-- -----------------------------------------------------------------------------
CREATE TABLE conversation (
    id                    NUMBER GENERATED BY DEFAULT AS IDENTITY,
    id_annonce            NUMBER NOT NULL,
    id_acheteur           NUMBER NOT NULL,
    -- Recopié depuis l'annonce : simplifie la liste "mes conversations"
    id_vendeur            NUMBER NOT NULL,
    date_creation         DATE   DEFAULT SYSDATE NOT NULL,
    date_dernier_message  DATE   DEFAULT SYSDATE NOT NULL,
    CONSTRAINT pk_conversation PRIMARY KEY (id),
    CONSTRAINT fk_conversation_annonce FOREIGN KEY (id_annonce) REFERENCES annonce (id) ON DELETE CASCADE,
    CONSTRAINT fk_conversation_acheteur FOREIGN KEY (id_acheteur) REFERENCES utilisateur (id),
    CONSTRAINT fk_conversation_vendeur FOREIGN KEY (id_vendeur) REFERENCES utilisateur (id),
    CONSTRAINT uq_conversation UNIQUE (id_annonce, id_acheteur),
    CONSTRAINT ck_conversation_participants CHECK (id_acheteur <> id_vendeur)
);
CREATE INDEX ix_conversation_acheteur ON conversation (id_acheteur);
CREATE INDEX ix_conversation_vendeur ON conversation (id_vendeur);

CREATE TABLE message (
    id               NUMBER GENERATED BY DEFAULT AS IDENTITY,
    id_conversation  NUMBER         NOT NULL,
    id_expediteur    NUMBER         NOT NULL,
    contenu          VARCHAR2(2000) NOT NULL,
    lu               NUMBER(1)      DEFAULT 0 NOT NULL,
    date_envoi       TIMESTAMP      DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_message PRIMARY KEY (id),
    CONSTRAINT fk_message_conversation FOREIGN KEY (id_conversation) REFERENCES conversation (id) ON DELETE CASCADE,
    CONSTRAINT fk_message_expediteur FOREIGN KEY (id_expediteur) REFERENCES utilisateur (id),
    CONSTRAINT ck_message_lu CHECK (lu IN (0, 1))
);
CREATE INDEX ix_message_conversation ON message (id_conversation, date_envoi);
CREATE INDEX ix_message_expediteur ON message (id_expediteur);

-- -----------------------------------------------------------------------------
-- Journal d'audit (rempli par les triggers TRG_AUDIT_*)
-- -----------------------------------------------------------------------------
CREATE TABLE journal_audit (
    id               NUMBER GENERATED BY DEFAULT AS IDENTITY,
    nom_table        VARCHAR2(30)   NOT NULL,
    id_ligne         NUMBER         NOT NULL,
    operation        VARCHAR2(6)    NOT NULL,
    -- Identifiant de l'utilisateur du site (posé par PHP) ou, à défaut, compte Oracle
    auteur           VARCHAR2(128)  NOT NULL,
    ancienne_valeur  VARCHAR2(4000),
    nouvelle_valeur  VARCHAR2(4000),
    date_action      TIMESTAMP      DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_journal_audit PRIMARY KEY (id),
    CONSTRAINT ck_journal_audit_operation CHECK (operation IN ('INSERT', 'UPDATE', 'DELETE'))
);
CREATE INDEX ix_journal_audit_cible ON journal_audit (nom_table, id_ligne);
CREATE INDEX ix_journal_audit_date ON journal_audit (date_action);
